# A156 is a helper of 500 sh steps called 500 times: 250,000 step copies, most of the time outside this rule
# (2.6 s at `653b153`, about 2.3 s after the slice on the building machine). It is not part of the time limit below.
SLOW = {"A156"}

CATALOG = load()


def verdict(text: str) -> str:
    result = jenkins.analyze("Jenkinsfile", text.encode(), CATALOG, None)
    found = [f for f in result.findings if f.rule == "OBAAF-JEN-009"]
    if found:
        order = {"high": 3, "medium": 2, "low": 1}
        return "finding-" + max(found, key=lambda f: order[f.severity]).severity
    row = next((row for row in jenkins.coverage(result, result.findings) if row["rule"] == "OBAAF-JEN-009"), None)
    if row is None or row["status"] in ("pass", "not applicable"):
        return "quiet"
    return row["status"]


RANK = {"quiet": 0, "unknown": 1, "finding-low": 2, "finding-medium": 3, "finding-high": 4}


class InjectionBypassTest(unittest.TestCase):
    def test_every_attempt(self):
        for name, expected, _before, _why, text in CASES:
            with self.subTest(case=name):
                self.assertEqual(verdict(text), expected)

    def test_limits_name_real_cases_whose_answer_differs(self):
        answers = {c[0]: c[1] for c in CASES}
        self.assertLessEqual(set(LIMITS), set(answers))
        for name, (judged, _why) in LIMITS.items():
            self.assertNotEqual(answers[name], judged, name)

    def test_no_stated_limit_is_quiet_where_a_finding_was_judged(self):
        # Only two limits are quiet where something was judged: text written to a file and run later (B-a19), and a
        # workspace file's contents (B-a13). Every other way past is a finding or cannot tell.
        allowed = {"B-a13", "B-a19", "A114"}
        answers = {c[0]: c[1] for c in CASES}
        for name, (judged, _why) in LIMITS.items():
            with self.subTest(case=name):
                if name not in allowed:
                    self.assertFalse(judged != "quiet" and answers[name] == "quiet")

    def test_no_attempt_is_slow(self):
        for name, _expected, _before, _why, text in CASES:
            if name in SLOW:
                continue
            started = time.monotonic()
            verdict(text)
            with self.subTest(case=name):
                self.assertLess(time.monotonic() - started, 3.0)

    def test_old_messages_kept_for_a_baseline(self):
        # A Jenkins finding's message is its identity in a baseline: where the rule reported a case before the slice,
        # with a source read directly or through one variable, it words it as before.
        texts = ['node { sh "echo ${env.CHANGE_TITLE}" }',
                 'node { sh "deploy ${params.TARGET}" }',
                 'node { def t = env.CHANGE_BRANCH\n sh "git checkout ${t}" }',
                 "node { def m = sh(script: 'git log -1 --pretty=%B', returnStdout: true).trim()\n sh \"echo ${m}\" }",
                 "pipeline { agent any\n parameters { string(name: 'TARGET') }\n stages { stage('a') { steps { "
                 "sh \"deploy ${TARGET}\" } } } }"]
        messages = []
        for text in texts:
            result = jenkins.analyze("Jenkinsfile", text.encode(), CATALOG, None)
            messages += [f.message for f in result.findings if f.rule == "OBAAF-JEN-009"]
        self.assertEqual(messages, [
            "The sh step in stage 'pipeline' builds its script with Groovy interpolation of CHANGE_TITLE. The value "
            "becomes part of the command before the shell runs, so it can run commands of its own.",
            "The sh step in stage 'pipeline' builds its script with Groovy interpolation of params.TARGET. The value "
            "becomes part of the command before the shell runs, so it can run commands of its own.",
            "The sh step in stage 'pipeline' builds its script with Groovy interpolation of t (from CHANGE_BRANCH). "
            "The value becomes part of the command before the shell runs, so it can run commands of its own.",
            "The sh step in stage 'pipeline' builds its script with Groovy interpolation of m (from git commit text). "
            "The value becomes part of the command before the shell runs, so it can run commands of its own.",
            "The sh step in stage 'a' builds its script with Groovy interpolation of parameter TARGET. The value "
            "becomes part of the command before the shell runs, so it can run commands of its own."])


